        while $(LPAREN)atomicLoad$(LPAREN)shouldContinue$(RPAREN)$(RPAREN)
        {
            immutable myUnitIndex = atomicOp!"+="$(LPAREN)workUnitIndex, 1$(RPAREN);
            immutable start = workUnitSize * myUnitIndex;
            if $(LPAREN)start >= len$(RPAREN)
            {
                atomicStore$(LPAREN)shouldContinue, false$(RPAREN);
                break;
            }

            immutable end = min$(LPAREN)len, start + workUnitSize$(RPAREN);

            foreach $(LPAREN)i; start .. end$(RPAREN)
            {
