"
    // Handle empty thread pool as special case.
    if $(LPAREN)pool.size == 0$(RPAREN)
    {
        return doSizeZeroCase$(LPAREN)this, dg$(RPAREN);
    }

    // Whether iteration is with or without an index variable.
    enum withIndex = Parameters!$(LPAREN)typeof$(LPAREN)dg$(RPAREN)$(RPAREN).length == 2;

    // This protects the range while copying it.
    auto rangeMutex = new Mutex$(LPAREN)$(RPAREN);

    shared bool shouldContinue = true;

    // The total number of elements that have been popped off range.
    // This is updated only while protected by rangeMutex;
    size_t nPopped = 0;

    static if $(LPAREN)
        is$(LPAREN)typeof$(LPAREN)range.buf1$(RPAREN)$(RPAREN) &&
        is$(LPAREN)typeof$(LPAREN)range.bufPos$(RPAREN)$(RPAREN) &&
        is$(LPAREN)typeof$(LPAREN)range.doBufSwap$(LPAREN)$(RPAREN)$(RPAREN)$(RPAREN)
    $(RPAREN)
    {
        // Make sure we don't have the buffer recycling overload of
        // asyncBuf.
        static if $(LPAREN)
            is$(LPAREN)typeof$(LPAREN)range.source$(RPAREN)$(RPAREN) &&
            isRoundRobin!$(LPAREN)typeof$(LPAREN)range.source$(RPAREN)$(RPAREN)
        $(RPAREN)
        {
            static assert$(LPAREN)0, "Cannot execute a parallel foreach loop on " ~
            "the buffer recycling overload of asyncBuf."$(RPAREN);
        }

        enum bool bufferTrick = true;
    }
    else
    {
        enum bool bufferTrick = false;
    }

    void doIt$(LPAREN)$(RPAREN)
    {
        scope$(LPAREN)failure$(RPAREN)
        {
            // If an exception is thrown, all threads should bail.
            atomicStore$(LPAREN)shouldContinue, false$(RPAREN);
        }

        static if $(LPAREN)hasLvalueElements!R$(RPAREN)
        {
            alias Temp = ElementType!R*[];
            Temp temp;

            // Returns:  The previous value of nPopped.
            size_t makeTemp$(LPAREN)$(RPAREN)
            {
                import std.algorithm.internal : addressOf;
                import std.array : uninitializedArray;

                if $(LPAREN)temp is null$(RPAREN)
                {
                    temp = uninitializedArray!Temp$(LPAREN)workUnitSize$(RPAREN);
                }

                rangeMutex.lock$(LPAREN)$(RPAREN);
                scope$(LPAREN)exit$(RPAREN) rangeMutex.unlock$(LPAREN)$(RPAREN);

                size_t i = 0;
                for $(LPAREN); i < workUnitSize && !range.empty; range.popFront$(LPAREN)$(RPAREN), i++$(RPAREN)
                {
                    temp[i] = addressOf$(LPAREN)range.front$(RPAREN);
                }

                temp = temp[0 .. i];
                auto ret = nPopped;
                nPopped += temp.length;
                return ret;
            }

        }
        else
        {

            alias Temp = ElementType!R[];
            Temp temp;

            // Returns:  The previous value of nPopped.
            static if $(LPAREN)!bufferTrick$(RPAREN) size_t makeTemp$(LPAREN)$(RPAREN)
            {
                import std.array : uninitializedArray;

                if $(LPAREN)temp is null$(RPAREN)
                {
                    temp = uninitializedArray!Temp$(LPAREN)workUnitSize$(RPAREN);
                }

                rangeMutex.lock$(LPAREN)$(RPAREN);
                scope$(LPAREN)exit$(RPAREN) rangeMutex.unlock$(LPAREN)$(RPAREN);

                size_t i = 0;
                for $(LPAREN); i < workUnitSize && !range.empty; range.popFront$(LPAREN)$(RPAREN), i++$(RPAREN)
                {
                    temp[i] = range.front;
                }

                temp = temp[0 .. i];
                auto ret = nPopped;
                nPopped += temp.length;
                return ret;
            }

            static if $(LPAREN)bufferTrick$(RPAREN) size_t makeTemp$(LPAREN)$(RPAREN)
            {
                import std.algorithm.mutation : swap;
                rangeMutex.lock$(LPAREN)$(RPAREN);
                scope$(LPAREN)exit$(RPAREN) rangeMutex.unlock$(LPAREN)$(RPAREN);

                // Elide copying by just swapping buffers.
                temp.length = range.buf1.length;
                swap$(LPAREN)range.buf1, temp$(RPAREN);

                // This is necessary in case popFront$(LPAREN)$(RPAREN) has been called on
                // range before entering the parallel foreach loop.
                temp = temp[range.bufPos..$(DOLLAR)];

                static if $(LPAREN)is$(LPAREN)typeof$(LPAREN)range._length$(RPAREN)$(RPAREN)$(RPAREN)
                {
                    range._length -= $(LPAREN)temp.length - range.bufPos$(RPAREN);
                }

                range.doBufSwap$(LPAREN)$(RPAREN);
                auto ret = nPopped;
                nPopped += temp.length;
                return ret;
            }
        }

        while $(LPAREN)atomicLoad$(LPAREN)shouldContinue$(RPAREN)$(RPAREN)
        {
            auto overallIndex = makeTemp$(LPAREN)$(RPAREN);
            if $(LPAREN)temp.empty$(RPAREN)
            {
                atomicStore$(LPAREN)shouldContinue, false$(RPAREN);
                break;
            }

            foreach $(LPAREN)i; 0 .. temp.length$(RPAREN)
            {
                scope$(LPAREN)success$(RPAREN) overallIndex++;

                static if $(LPAREN)hasLvalueElements!R$(RPAREN)
                {
                    static if $(LPAREN)withIndex$(RPAREN)
                    {
                        if $(LPAREN)dg$(LPAREN)overallIndex, *temp[i]$(RPAREN)$(RPAREN) foreachErr$(LPAREN)$(RPAREN);
                    }
                    else
                    {
                        if $(LPAREN)dg$(LPAREN)*temp[i]$(RPAREN)$(RPAREN) foreachErr$(LPAREN)$(RPAREN);
                    }
                }
                else
                {
                    static if $(LPAREN)withIndex$(RPAREN)
                    {
                        if $(LPAREN)dg$(LPAREN)overallIndex, temp[i]$(RPAREN)$(RPAREN) foreachErr$(LPAREN)$(RPAREN);
                    }
                    else
                    {
                        if $(LPAREN)dg$(LPAREN)temp[i]$(RPAREN)$(RPAREN) foreachErr$(LPAREN)$(RPAREN);
                    }
                }
            }
        }
    }

    submitAndExecute$(LPAREN)pool, &doIt$(RPAREN);

    return 0;
"
